"use client"; import { useQuery, useMutation, useQueryClient } from "@tanstack/react-query"; import { api } from "@/lib/api/services"; import { LoadingState, EmptyState, ErrorState } from "@/components/PageStates"; import { Button } from "@/components/ui/button"; import { Input } from "@/components/ui/input"; import { Textarea } from "@/components/ui/textarea"; import { Label } from "@/components/ui/label"; import { Badge } from "@/components/ui/badge"; import { Card, CardHeader, CardTitle, CardContent } from "@/components/ui/card"; import { formatDate } from "@/lib/utils"; import Link from "next/link"; import { useState } from "react";
export default function Documents(){const [ft,setFt]=useState("");const [st,setSt]=useState("");const [search,setSearch]=useState("");const [wsid,setWsid]=useState("");
 const qs=`?limit=50&offset=0${ft?`&file_type=${ft}`:""}${st?`&status=${st}`:""}${search?`&search=${encodeURIComponent(search)}`:""}${wsid?`&workspace_id=${wsid}`:""}`;
 const q=useQuery({queryKey:["documents",qs],queryFn:()=>api.documents(qs)});
 return <div><h1 className="text-2xl font-semibold tracking-tight">Documents</h1><p className="mt-1 text-sm text-zinc-400">Every source across your workspaces.</p>
 <div className="mt-5 flex flex-wrap gap-2"><Input className="max-w-xs" placeholder="Search filename…" value={search} onChange={e=>setSearch(e.target.value)} aria-label="Search documents"/><select value={ft} onChange={e=>setFt(e.target.value)} className="h-9 rounded-md border border-white/10 bg-zinc-900 px-3 text-sm" aria-label="File type"><option value="">All types</option><option value="pdf">PDF</option><option value="docx">DOCX</option><option value="txt">TXT</option></select><select value={st} onChange={e=>setSt(e.target.value)} className="h-9 rounded-md border border-white/10 bg-zinc-900 px-3 text-sm" aria-label="Status"><option value="">Any status</option><option value="uploaded">Uploaded</option><option value="processed">Processed</option><option value="failed">Failed</option></select><Input className="max-w-[200px]" placeholder="Workspace ID (optional)" value={wsid} onChange={e=>setWsid(e.target.value)}/></div>
 <div className="mt-5">{q.isLoading?<LoadingState/>:q.error?<ErrorState message="Failed to load documents" onRetry={()=>q.refetch()}/>:!q.data?.length?<EmptyState title="No documents match" desc="Upload documents inside a workspace to see them here."/>:<div className="overflow-x-auto rounded-lg border border-white/[0.08]"><table className="w-full min-w-[640px] text-left text-sm"><thead className="bg-zinc-900 text-xs text-zinc-400"><tr><th className="px-4 py-3 font-medium">File</th><th className="px-4 py-3 font-medium">Type</th><th className="px-4 py-3 font-medium">Status</th><th className="px-4 py-3 font-medium">Added</th></tr></thead><tbody>{q.data.map(d=><tr key={d.id} className="border-t border-white/[0.06]"><td className="px-4 py-3 font-medium">{d.original_filename||d.filename}</td><td className="px-4 py-3 uppercase text-zinc-400">{d.file_type}</td><td className="px-4 py-3"><Badge>{d.status}</Badge></td><td className="px-4 py-3 text-zinc-400">{formatDate(d.created_at)}</td></tr>)}</tbody></table></div>}</div></div>;}
